RSpec.describe "Seed refusal once a Timekeeping handoff has begun" do
  # "`db/seeds.rb`: refuse right after `TimekeepingOwnership.ensure_initial!` (line 155) and before the company update."
  it "db/seeds.rb refuses before the company update while a handoff step is set" do
    allow($stdout).to receive(:write)
    company = create(:company, name: "Fork & Leaf Salads", business_phone: "+1 2025550123")
    TimekeepingOwnership.current.update_columns(handoff_step: "settle")
    expect(company.reload.business_phone).to eq("+1 2025550123")

    expect { load Rails.root.join("db/seeds.rb") }.to raise_error(TimekeepingOwnership::HandoffBegun)

    expect(company.reload.business_phone).to eq("+1 2025550123")
    expect(TimekeepingOwnership.pluck(:handoff_step)).to eq(["settle"])
  end
end

